public async Task RunAsync(string queueUrl, CancellationToken stoppingToken)
{
    while (!stoppingToken.IsCancellationRequested)
    {
        using var linked = CancellationTokenSource
            .CreateLinkedTokenSource(stoppingToken);
        linked.CancelAfter(TimeSpan.FromSeconds(25));

        try
        {
            var response = await _sqs.ReceiveMessageAsync(queueUrl, linked.Token);
            foreach (var message in response.Messages)
            {
                await HandleAsync(message, stoppingToken);
                await _sqs.DeleteMessageAsync(queueUrl, message.ReceiptHandle, stoppingToken);
            }
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            break; // host shutdown — exit gracefully
        }
        catch (OperationCanceledException)
        {
            continue; // receive timeout — try again
        }
    }
}

public async Task ProcessBatchAsync(
    IReadOnlyList<Row> rows, CancellationToken cancellationToken)
{
    foreach (var row in rows)
    {
        cancellationToken.ThrowIfCancellationRequested();
        await TransformAndSaveAsync(row, cancellationToken);
    }
}

